package org.apache.commons.text;

import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringSubstitutor_ESTest_test37 extends StringSubstitutor_ESTest_scaffolding {

    /** A newly allocated CharBuffer is filled with the NUL character (�). */
    private static final char NUL = '�';

    /**
     * Verifies that replacing a CharSequence that contains no variable
     * references returns the text unchanged.
     *
     * The input is a freshly allocated CharBuffer of 36 characters (the numeric
     * value of '$' is 36), so it holds 36 NUL characters. Because the text
     * contains no "${...}" placeholders, the substitutor returns it verbatim:
     * a string of 36 NUL characters.
     */
    @Test(timeout = 4000)
    public void replaceTextWithoutVariablesReturnsItUnchanged() throws Throwable {
        StringSubstitutor substitutor = new StringSubstitutor();

        int bufferLength = '$'; // 36
        CharBuffer textWithoutVariables = CharBuffer.allocate(bufferLength);

        String result = substitutor.replace((CharSequence) textWithoutVariables);

        assertNotNull(result);
        // The default escape character is '$' and is left untouched.
        assertEquals('$', substitutor.getEscapeChar());

        StringBuilder expected = new StringBuilder();
        for (int i = 0; i < bufferLength; i++) {
            expected.append(NUL);
        }
        assertEquals(expected.toString(), result);
    }
}
